import numpy as np
from PIL import Image,ImageDraw
from scipy.interpolate import PchipInterpolator
Z=np.load('/app/output/current_masks.npz');R=Z['ink'];T=Z['target'];base=(R&T).sum()/(R|T).sum()
pts=np.array([[273,486],[260,493],[249,505],[244,520],[247,535],[260,549],[281,557]],float)
def score(P,off=0):
 t=np.r_[0,np.cumsum(np.linalg.norm(np.diff(P,axis=0),axis=1))];v=np.linspace(0,t[-1],int(t[-1]*2));p=np.array([PchipInterpolator(t,P[:,j])(v) for j in range(2)]).T;dxy=np.gradient(p,axis=0);a=np.arctan2(-dxy[:,1],dxy[:,0])+np.deg2rad(off);im=Image.new('1',(570,150));d=ImageDraw.Draw(im)
 for (u,y),th in zip(p,a):
  dx=8*np.cos(th);dy=-8*np.sin(th);d.line((round(u-dx-220),round(y-dy-430),round(u+dx-220),round(y+dy-430)),fill=1,width=1)
 S=np.array(im).astype(bool);A=R|S;return (A&T).sum()/(A|T).sum(),((S&~R)&T).sum(),((S&~R)&~T).sum()
B=(0,None)
for du in range(-5,6):
 for dv in range(-5,6):
  for a in range(-30,31,10):
   q,tp,fp=score(pts+[du,dv],a)
   if q>B[0]:B=(q,(du,dv,a,tp,fp))
print('base',base,'best',B)
